"""Reference rates published by the treasury rate service."""

from dataclasses import dataclass
from decimal import Decimal
import json
import re
import urllib.request
from typing import Any

RATES_URL = "https://fx.treasury.internal/v1/rates"


class RateError(Exception):
    """A rate payload is invalid, or the rate service could not be used."""


@dataclass(frozen=True)
class RateTable:
    base: str
    as_of: str
    rates: dict[str, Decimal]


def parse_rates(text: str) -> RateTable:
    """Parse a rate service response body. See README.md for the rules."""
    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        raise RateError(f"Invalid JSON: {e}")

    if not isinstance(data, dict):
        raise RateError("Payload must be an object")

    if "base" not in data:
        raise RateError("Missing base currency")

    base = data["base"]
    if not isinstance(base, str):
        raise RateError("Base currency must be a string")

    if "as_of" not in data:
        raise RateError("Missing as_of timestamp")

    as_of = data["as_of"]
    if not isinstance(as_of, str):
        raise RateError("as_of must be a string")

    if "rates" not in data:
        raise RateError("Missing rates object")

    rates_data = data["rates"]
    if not isinstance(rates_data, dict):
        raise RateError("rates must be an object")

    rates = {}
    for currency, rate_str in rates_data.items():
        if not isinstance(currency, str) or not re.match(r"^[A-Z]{3}$", currency):
            raise RateError(f"Invalid currency code: {currency}")
        if not isinstance(rate_str, str):
            raise RateError(f"Rate for {currency} must be a string")
        try:
            rate_decimal = Decimal(rate_str)
        except:
            raise RateError(f"Invalid rate for {currency}: {rate_str}")
        if rate_decimal <= 0 or not rate_decimal.is_finite():
            raise RateError(f"Rate for {currency} must be positive and finite")

        rates[currency] = rate_decimal

    # Ensure base currency is in rates with rate 1
    rates[base] = Decimal(1)

    return RateTable(base=base, as_of=as_of, rates=rates)


def fetch_rates(base: str = "EUR", *, timeout: float = 5.0) -> RateTable:
    """Fetch the current rates for `base` from the rate service."""
    if not isinstance(base, str) or not re.match(r"^[A-Z]{3}$", base):
        raise RateError("Base currency must be three uppercase letters")

    url = f"{RATES_URL}?base={base}"
    try:
        with urllib.request.urlopen(url, timeout=timeout) as response:
            if response.getcode() != 200:
                raise RateError(f"rate service unavailable: HTTP {response.getcode()}")
            body = response.read().decode('utf-8')
            return parse_rates(body)
    except Exception as e:
        raise RateError(f"rate service unavailable: {e}")
